import React, { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import WeiterButton from "../components/WeiterButton";
import AlphabetShiftigTool from "../components/tools/AlphabetShiftingTool";
import HaeufigkeitsanalyseTool from "../components/tools/HaeufigkeitsanalyseTool";

export default function Kryptoanalyse() {
  const navigate = useNavigate();

  useEffect(() => {
    const passed = localStorage.getItem("level1Passed");
    if (passed !== "true") {
      navigate("/zugriffsfehler");
    }
  }, [navigate]);

  return (
    <div className="text-style">
      <h1 className="text-2xl font-bold heading-style mb-4">Let's see what we have...</h1>
      <p className="mb-4">
        Du hast dir in Bagdad ein Zimmer gemietet, um über das nachzudenken, was du inzwischen gelernt hast.
        Das Verschiebeverfahren war noch nicht besonders sicher – doch wie sieht es mit dem Ersetzungsverfahren aus?
        Du beschließt, zunächst nochmal einen Blick auf das Caesar-Verfahren zu werfen...
      </p>

      <AlphabetShiftingTool />

      <p className="mb-4">
        Das Ausprobieren funktioniert problemlos, aber du erkennst, dass es auch einen systematischen Weg gibt, das Caesar-Verfahren zu knacken.
        Dafür zählst du die Häufigkeit der Buchstaben im Geheimtext und bildest die Buchstaben entsprechend der Häufigkeit in der Klartext-Sprache aufeinander ab.
        Wenn du also herausfindest, welche Buchstaben im Geheimtext besonders häufig vorkommen, kannst du versuchen, diese mit den häufigsten Buchstaben in Klartexten zu vergleichen.
        Am häufigsten ist im Deutschen z. B. das „E“, gefolgt von „N“, „I“, „S“ usw. Im Deutschen finden sich die folgenden Buchstabenhäufigkeiten:
      </p>
      <div className="flex gap-2 mt-2 text-xs items-end">
        {Object.entries({
          E: 17.40, N: 9.78, I: 7.55, S: 7.27, R: 7.00, A: 6.51, T: 6.15, D: 5.08, H: 4.76, U: 4.35,
          L: 3.44, C: 3.06, G: 3.01, M: 2.53, O: 2.51, B: 1.89, W: 1.89, F: 1.66, K: 1.21, Z: 1.13,
          P: 0.79, V: 0.67, J: 0.27, Y: 0.04, X: 0.03, Q: 0.02
        }).map(([char, freq]) => (
          <div key={char} className="text-center">
            <div
              className="bg-white/20 mx-auto"
              style={{ height: `${(freq / 17.4) * 100}px`, width: "12px" }}
            ></div>
            <div>{char}</div>
          </div>
        ))}
      </div>

      <p className="mt-6">
        Nun betrachtest du das Ersetzungsverfahren – kann man auch hier mithilfe der Häufigkeit der Buchstaben den Klartext erraten?
        Probiere es selbst aus:
      </p>

      <HaeufigkeitsanalyseTool />

      <div className="mb-8">
        <h2 className="text-xl font-bold heading-style mb-2">Vergleich der Sicherheit</h2>
        <p>
          Du hast herausgefunden: Das Caesar-Verfahren ist leicht durch Brute-Force knackbar – es gibt nur 26 mögliche Schlüssel.
          Beim Ersetzungsverfahren sind es 26! Möglichkeiten – viel zu viele zum Raten.
          Aber auch hier hilft die Häufigkeitsanalyse – allerdings nur, wenn der Text lang genug ist, um die Buchstabenverteilung sinnvoll auszuwerten.
        </p>
      </div>

      <WeiterButton to="/level2/fachkonzepte" />
    </div>
  );
}
